#!/usr/bin/env bash
# install.py in a throwaway HOME and project: every CLI, both scopes, rerun,
# conflicts, hooks merge, links into dist, uninstall. Touches nothing outside a
# temp dir (ORC_DIST keeps the generated files out of this repo's dist/).
#   bash tests/test_install.sh
set -u
cd "$(dirname "$0")/.."
REPO=$PWD
pass=0; fail=0
check() { if eval "$2"; then pass=$((pass+1)); else fail=$((fail+1)); echo "FAIL: $1"; fi; }

T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
export HOME=$T/home ORC_DIST=$T/dist; unset XDG_CONFIG_HOME CODEX_HOME
mkdir -p "$HOME/.claude" "$HOME/.cursor/agents" "$T/proj"
echo '{"theme": "dark", "hooks": {"PreToolUse": [{"matcher": "Edit", "hooks": [{"type": "command", "command": "mine.sh"}]}]}}' > "$HOME/.claude/settings.json"
# A copy from before installs were links: ours, so it becomes a link.
echo '# Generated by herdr-orchestrators install.py from somewhere' > "$HOME/.cursor/agents/review-risk.md"
# --no-mods: never touch the real Claude plugin state; the mods get a dry-run check below.
I() { python3 "$REPO/install.py" --cli claude,opencode,agy,codex,cursor --no-mods "$@"; }

# 1. global install, every CLI
check "global install succeeds" "I >/dev/null"
for f in .claude/agents/hcorc.md .claude/agents/review-risk.md .claude/commands/herdorc-panes.md \
         .config/opencode/agents/herdorc.md .config/opencode/commands/hcorc-status.md \
         .gemini/config/agents/hcorc/agent.md .gemini/config/agents/jd-judge-a/agent.md \
         .codex/hcorc.config.toml .codex/agents/gentle-ai-worker.toml \
         .cursor/skills/herdorc/SKILL.md .cursor/skills/herdorc/prompt.md .cursor/agents/review-refuter.md; do
  check "installed $f as a link into dist" "[ -L '$HOME/$f' ] && [ \"\$(readlink '$HOME/$f')\" = '$ORC_DIST/home/$f' ] && [ -s '$HOME/$f' ]"
done
check "an old copy became a link" "[ -L $HOME/.cursor/agents/review-risk.md ] && grep -q '^readonly: true' $HOME/.cursor/agents/review-risk.md"
check "status counts links" "python3 '$REPO/install.py' --status | grep '^claude ' | grep -q 'links=' && ! python3 '$REPO/install.py' --status | grep -q -E 'BROKEN|copies='"
S=$HOME/.claude/settings.json
check "user settings kept (theme, own hook)" "python3 -c \"import json;d=json.load(open('$S'));assert d['theme']=='dark';assert any(h['hooks'][0]['command']=='mine.sh' for h in d['hooks']['PreToolUse'])\""
check "guard + phase hooks added once, absolute" "[ \$(grep -c 'shared/bin/guard.py' '$S') = 1 ] && grep -q '$REPO/shared/bin/orc.py phase --hook' '$S'"
check "settings backup written" "[ -f '$S.orc-backup' ]"

# 2. per-CLI content
check "claude prompt: hooks text, own vocabulary, no --as" "grep -q 'A PreToolUse hook' $HOME/.claude/agents/hcorc.md && grep -q '# Tool vocabulary (Claude Code)' $HOME/.claude/agents/hcorc.md && ! grep -q -- '--as hcorc' $HOME/.claude/agents/hcorc.md"
check "opencode prompt: glossary, --as, no-hook rules, mode primary" "grep -q '# Tool vocabulary (OpenCode)' $HOME/.config/opencode/agents/hcorc.md && grep -q -- 'orc.py --as hcorc' $HOME/.config/opencode/agents/hcorc.md && grep -q 'No hook enforces' $HOME/.config/opencode/agents/hcorc.md && grep -q '^mode: primary' $HOME/.config/opencode/agents/hcorc.md"
check "opencode read-only role denies edit, worker does not" "grep -q 'effect: deny' $HOME/.config/opencode/agents/review-risk.md && ! grep -q 'permissions' $HOME/.config/opencode/agents/gentle-ai-worker.md"
check "opencode command runs under its agent" "grep -q '^agent: herdorc' $HOME/.config/opencode/commands/herdorc-panes.md"
check "agy roles: subagent only, exact tools" "grep -q '^mainAgent: false' $HOME/.gemini/config/agents/review-risk/agent.md && grep -q 'run_command' $HOME/.gemini/config/agents/review-risk/agent.md && ! grep -q -E 'mcp__|Bash' $HOME/.gemini/config/agents/review-risk/agent.md"
check "herdorc embeds the herdr skill" "grep -q 'The \`herdr\` skill follows' $HOME/.gemini/config/agents/herdorc/agent.md"
# tomllib is Python 3.11+; the scripts support 3.9, so older Pythons get a smaller check.
if python3 -c 'import tomllib' 2>/dev/null; then
check "codex TOML parses; sandbox by role" "python3 -c \"
import tomllib;h='$HOME/.codex'
w=tomllib.load(open(h+'/agents/gentle-ai-worker.toml','rb'));r=tomllib.load(open(h+'/agents/review-risk.toml','rb'));p=tomllib.load(open(h+'/hcorc.config.toml','rb'))
assert w['sandbox_mode']=='workspace-write' and r['sandbox_mode']=='read-only' and r['name']=='review-risk'
assert 'Tool vocabulary (Codex CLI)' in p['developer_instructions']\""
else
check "codex sandbox by role (no tomllib)" "grep -q '^sandbox_mode = \"workspace-write\"' $HOME/.codex/agents/gentle-ai-worker.toml && grep -q '^sandbox_mode = \"read-only\"' $HOME/.codex/agents/review-risk.toml"
fi
check "cursor skill points at its prompt; read-only role" "grep -q \"$HOME/.cursor/skills/hcorc/prompt.md\" $HOME/.cursor/skills/hcorc/SKILL.md && grep -q '^readonly: true' $HOME/.cursor/agents/review-risk.md && ! grep -q readonly $HOME/.cursor/agents/gentle-ai-worker.md"
check "no unfilled placeholders or conditionals anywhere" "! grep -r -l -E '\{\{[A-Z_]+\}\}|<!-- (if:|endif)' '$ORC_DIST'"

# 3. rerun is a no-op; a pull that changes a prompt rewrites the target, not the link
check "rerun changes nothing" "I | grep -q '^\[claude\] updated 0 of'"
check "rerun keeps one guard hook" "[ \$(grep -c 'shared/bin/guard.py' '$S') = 1 ]"
echo stale > "$ORC_DIST/home/.claude/agents/hcorc.md"
check "a changed target is regenerated behind the same link" "I | grep -q '^\[claude\] updated 1 of' && grep -q 'Tool vocabulary' $HOME/.claude/agents/hcorc.md && [ -L $HOME/.claude/agents/hcorc.md ]"
rm "$ORC_DIST/home/.claude/agents/review-risk.md"
check "status flags a broken link" "python3 '$REPO/install.py' --status | grep '^claude ' | grep -q 'BROKEN=1'"
check "rerun repairs it" "I >/dev/null && [ -s $HOME/.claude/agents/review-risk.md ]"

# 4. project scope + a file we did not write
mkdir -p "$T/proj/.opencode/agents"; echo "mine" > "$T/proj/.opencode/agents/hcorc.md"
OUT=$(I --scope project --project "$T/proj" 2>&1)
check "foreign file blocks that CLI only" "echo \"\$OUT\" | grep -q 'opencode\] not installed' && [ \"\$(cat $T/proj/.opencode/agents/hcorc.md)\" = mine ] && [ -s $T/proj/.claude/agents/hcorc.md ]"
check "project claude hooks are absolute (not this repo)" "grep -q '$REPO/shared/bin/guard.py' $T/proj/.claude/settings.json"
check "--force overwrites it" "I --scope project --project '$T/proj' --cli opencode --force >/dev/null && grep -q 'mode: primary' $T/proj/.opencode/agents/hcorc.md"
check "codex profiles shared by both scopes" "[ -s $HOME/.codex/herdorc.config.toml ]"

# 5. --agents narrows and removes the dropped one
I --agents hcorc >/dev/null
check "dropped orchestrator removed, roles kept" "[ ! -e $HOME/.claude/agents/herdorc.md ] && [ ! -e $HOME/.gemini/config/agents/herdorc ] && [ -s $HOME/.claude/agents/review-risk.md ]"

# 6. uninstall
I --uninstall >/dev/null
check "global uninstall removes our links" "[ ! -L $HOME/.claude/agents/hcorc.md ] && [ ! -e $HOME/.cursor/skills/hcorc ] && [ ! -e $HOME/.gemini/config/agents/review-risk ]"
check "and the generated files behind them" "[ ! -e '$ORC_DIST/home/.claude/agents/hcorc.md' ] && [ ! -e '$ORC_DIST/home/.cursor' ]"
check "codex profile kept while the project install uses it" "[ -s $HOME/.codex/hcorc.config.toml ]"
check "hooks removed, user settings kept" "! grep -q 'shared/bin/guard.py' '$S' && grep -q mine.sh '$S' && grep -q dark '$S'"
I --uninstall --scope project --project "$T/proj" >/dev/null
check "project uninstall removes the rest" "[ ! -e $T/proj/.claude/agents/hcorc.md ] && [ ! -e $HOME/.codex/hcorc.config.toml ]"
check "status empty" "python3 '$REPO/install.py' --status | grep -q 'no installs'"

# 7. the Claude-only mods: planned for claude, never for another CLI
if [ -f "$REPO/.claude-plugin/marketplace.json" ] && command -v claude >/dev/null; then
  check "dry-run plans the mod plugins for claude" "python3 '$REPO/install.py' --cli claude --dry-run | grep -q 'would run: claude plugin install'"
  check "no mods for other CLIs" "! python3 '$REPO/install.py' --cli opencode,agy,codex,cursor --dry-run | grep -q 'claude plugin'"
fi

# 8. a broken settings.json aborts without writing
echo '{oops' > "$S"
check "invalid settings.json refused" "! I --cli claude >/dev/null 2>&1 && [ \"\$(cat '$S')\" = '{oops' ]"
echo '{"hooks": {"PreToolUse": null}}' > "$S"
check "a hooks event that is not a list is refused before any link" "! I --cli claude >/dev/null 2>&1 && [ ! -e $HOME/.claude/agents/hcorc.md ] && grep -q null '$S'"
echo '{"hooks": {"PreToolUse": [{"matcher": "Bash", "hooks": [{"type": "command", "command": true}]}]}}' > "$S"
check "a hook whose command is not text is refused before any link" "! I --cli claude >/dev/null 2>&1 && [ ! -e $HOME/.claude/agents/hcorc.md ] && grep -q true '$S'"
echo '{}' > "$S"; I --cli claude >/dev/null; echo '{oops' > "$S"
check "uninstall with broken settings keeps the record" "I --cli claude --uninstall | grep -q 'hooks left in place' && python3 '$REPO/install.py' --status | grep -q '^claude ' && [ ! -L $HOME/.claude/agents/hcorc.md ]"
echo '{}' > "$S"
check "and a later uninstall removes the hooks and the record" "I --cli claude --uninstall | grep -q 'hooks removed' && ! grep -q guard.py '$S' && ! python3 '$REPO/install.py' --status | grep -q '^claude '"
check "save_manifest keeps entries another run saved meanwhile" "python3 -c \"
import json, sys; sys.path.insert(0, '$REPO'); import install as I
m = I.load_manifest(); m['mine|x|y'] = {'files': []}
p = I.manifest_path(); p.parent.mkdir(parents=True, exist_ok=True)
other = I.read_manifest(); other['theirs|x|y'] = {'files': []}; p.write_text(json.dumps(other))
I.save_manifest(m); d = json.loads(p.read_text()); assert 'mine|x|y' in d and 'theirs|x|y' in d, d
m.pop('mine|x|y'); I.save_manifest(m); d = json.loads(p.read_text()); assert 'mine|x|y' not in d and 'theirs|x|y' in d, d
d.pop('theirs|x|y'); p.write_text(json.dumps(d))\""
check "Skills bar: a reinstall puts the button back beside a third-party sibling" "python3 -c \"
import sys; sys.path.insert(0, '$REPO'); import install as I
t = {'id': 'w', 'type': 'column', 'children': [{'id': 'orc-skills-bar', 'type': 'row', 'children': [{'id': 'tabs', 'type': 'block'}, {'id': 'other', 'type': 'block'}]}, {'id': 'work-body', 'type': 'row', 'children': []}]}
assert I.herdr_patch(t); ids = [c['id'] for c in t['children'][0]['children']]; assert ids == ['tabs', 'other', 'orc-skills-toggle'], ids
assert I.herdr_patch(t); assert [c['id'] for c in t['children'][0]['children']].count('orc-skills-toggle') == 1\""

# 9. the Herdr desktop Skills panel, in a throwaway Herdr home. A stub
# herdr-app stands in for the real one, so no window is ever asked.
H=$T/herdr; mkdir -p "$H/layouts" "$T/bin"
export HERDR_APP_HOME=$H
printf '#!/bin/sh\necho "$*" >> "%s/herdr-calls"\n[ "$1" = check ] && exit 0\nexit 1\n' "$T" > "$T/bin/herdr-app"; chmod +x "$T/bin/herdr-app"
HP() { PATH="$T/bin:$PATH" python3 "$REPO/install.py" --herdr-app "$@"; }
cat > "$H/layouts/main.json" <<'EOF'
{"id": "root", "type": "row", "children": [{"id": "work", "type": "column", "children": [
  {"id": "tabs", "type": "block", "size": {"px": 42}, "window_drag": true, "content": {"mod": "tabs"}},
  {"id": "work-body", "type": "row", "children": [{"id": "main", "type": "block", "content": {"tab": "active"}},
    {"id": "panel", "type": "column", "hidden": true, "children": []}]}]}]}
EOF
echo '{"layout:main": {"json": "x"}}' > "$H/installed.json"; echo '{"layout": "main"}' > "$H/shared.json"
L=$H/layouts/main-orc.json
check "herdr-app: shipped layout cloned, not edited" "HP >/dev/null && [ -f '$L' ] && grep -q '\"tabs\"' '$H/layouts/main.json' && ! grep -q orc-skills '$H/layouts/main.json'"
check "herdr-app: button and hidden panel added" "python3 -c \"import json;s=open('$L').read();d=json.loads(s);assert s.count('orc-skills-toggle')==1 and s.count('orc-skills-panel')==1;assert '\\\"hidden\\\": true' in s\""
check "herdr-app: config points at this clone" "grep -q '$REPO/shared/bin/orc.py' '$H/mods/orc-skills/config.js' && [ -f '$H/mods/orc-skills/main.js' ]"
check "herdr-app: the mod folder is a link to its build in dist" "[ \"\$(readlink '$H/mods/orc-skills')\" = '$ORC_DIST/abs${H}/mods/orc-skills' ] && cmp -s '$H/mods/orc-skills/main.js' '$REPO/herdr-app/mods/orc-skills/main.js'"
check "herdr-app: the repo's placeholder config is untouched" "grep -q 'export const ORC = \"\"' '$REPO/herdr-app/mods/orc-skills/config.js'"
check "herdr-app: herdr-app check ran" "grep -q '^check $H/mods/orc-skills' '$T/herdr-calls'"
M0=$(stat -f %m "$L" 2>/dev/null || stat -c %Y "$L"); sleep 1
check "herdr-app: rerun adds nothing twice, leaves the layout file alone" "HP >/dev/null && [ \$(grep -c orc-skills-panel '$L') = 1 ] && [ \$(stat -f %m '$L' 2>/dev/null || stat -c %Y '$L') = $M0 ]"
check "herdr-app: status lists it" "python3 '$REPO/install.py' --status | grep -q 'herdr-app.*layout=main-orc'"
check "herdr-app: uninstall removes link, build and cloned layout, keeps the sources" "HP --uninstall >/dev/null && [ ! -L '$H/mods/orc-skills' ] && [ ! -e '$L' ] && [ -s '$REPO/herdr-app/mods/orc-skills/main.js' ] && [ ! -e '$ORC_DIST/abs${H}/mods/orc-skills' ]"
mkdir -p "$H/mods/orc-skills" && echo old > "$H/mods/orc-skills/main.js" && touch "$H/mods/orc-skills/.orc-generated"
check "herdr-app: a copy from before links becomes a link" "HP >/dev/null && [ -L '$H/mods/orc-skills' ] && HP --uninstall >/dev/null"
cp "$H/layouts/main.json" "$H/layouts/mine.json"; echo '{"layout": "mine"}' > "$H/shared.json"
check "herdr-app: a personal layout is patched in place" "HP >/dev/null && grep -q orc-skills-panel '$H/layouts/mine.json' && [ ! -e '$L' ]"
check "herdr-app: uninstall restores the personal layout" "HP --uninstall >/dev/null && python3 -c \"import json;a=json.load(open('$H/layouts/mine.json'));b=json.load(open('$H/layouts/main.json'));assert a==b,(a,b)\""
mkdir -p "$H/mods/orc-skills" && echo mine > "$H/mods/orc-skills/main.js"
check "herdr-app: someone else's orc-skills mod is refused" "! HP >/dev/null && [ \"\$(cat '$H/mods/orc-skills/main.js')\" = mine ]"

# 10. installers/<cli>.sh: one target, user or project scope
P2=$T/proj2; mkdir -p "$P2"
check "installers/agy.sh --scope project links into the project" "'$REPO/installers/agy.sh' --scope project --project '$P2' >/dev/null && [ -L '$P2/.agents/agents/hcorc/agent.md' ]"
check "installers/agy.sh --uninstall --scope project removes them" "'$REPO/installers/agy.sh' --uninstall --scope project --project '$P2' >/dev/null && [ ! -e '$P2/.agents/agents/hcorc/agent.md' ]"
check "--scope user is the home folder, recorded as global" "'$REPO/installers/agy.sh' --scope user >/dev/null && [ -L '$HOME/.gemini/config/agents/hcorc/agent.md' ] && python3 '$REPO/install.py' --status | grep -q '^agy *global'"
check "installers/agy.sh --help shows its usage" "'$REPO/installers/agy.sh' --help | grep -q 'scope project'"

# 11. install.py --herdr: orc-flow in the herdr TUI. A stub herdr records the
# calls, and the keybinding goes to an isolated XDG_CONFIG_HOME.
X=$T/xdg; mkdir -p "$X"
cat > "$T/bin/herdr" <<EOF
#!/bin/sh
echo "\$*" >> "$T/herdr-tui-calls"
case "\$1 \$2" in
  "plugin list") [ -f "$T/linked" ] && echo "- orc-flow (orc-flow) enabled [local:\$(cat "$T/linked")]"; exit 0 ;;
  "plugin link") echo "\$3" > "$T/linked"; exit 0 ;;
  "plugin unlink") rm -f "$T/linked"; exit 0 ;;
esac
exit 1
EOF
chmod +x "$T/bin/herdr"
HT() { PATH="$T/bin:$PATH" XDG_CONFIG_HOME=$X python3 "$REPO/install.py" --herdr "$@"; }
check "herdr: links orc-flow from this clone" "HT >/dev/null && [ \"\$(cat '$T/linked')\" = '$REPO/herdr/plugins/orc-flow' ]"
check "herdr: binds prefix+shift+z in herdr's config" "grep -q 'orc-flow.open' '$X/herdr/config.toml'"
check "herdr: a rerun links only once" "HT >/dev/null && [ \$(grep -c '^plugin link' '$T/herdr-tui-calls') = 1 ]"
check "herdr: status lists it" "XDG_CONFIG_HOME=$X python3 '$REPO/install.py' --status | grep -q '^herdr .*orc-flow'"
check "herdr: uninstall unlinks and removes the key block" "HT --uninstall >/dev/null && [ ! -f '$T/linked' ] && ! grep -q orc-flow '$X/herdr/config.toml'"

# 12. herdr-app/extras.py with a stand-in list and local sources: no network.
SRC=$T/src; mkdir -p "$SRC/acme-mods/alpha/mods/alpha" "$SRC/acme-mods/tree/mods/tree" "$SRC/acme-tool"
echo '{"name": "alpha"}' > "$SRC/acme-mods/alpha/mods/alpha/mod.json"
echo 'const V = 1;' > "$SRC/acme-mods/alpha/mods/alpha/main.js"
echo '{"name": "tree"}' > "$SRC/acme-mods/tree/mods/tree/mod.json"
printf '%s\n' '--- a/mods/alpha/main.js' '+++ b/mods/alpha/main.js' '@@ -1 +1 @@' '-const V = 1;' '+const V = 2;' > "$T/alpha.patch"
printf '%s\n' 'if [ "$1" = --uninstall ]; then rm -f "$HERDR_APP_HOME/tool-installed"; else echo "$*" > "$HERDR_APP_HOME/tool-installed"; fi' > "$SRC/acme-tool/install.sh"
cat > "$T/spec.json" <<EOF
{"mods": {
 "tool": {"repo": "acme/tool", "ref": "1111111111", "license": "MIT", "about": "t",
          "installer": ["sh", "install.sh", "--app"], "uninstaller": ["sh", "install.sh", "--uninstall"]},
 "alpha": {"repo": "acme/mods", "ref": "2222222222", "license": "MIT", "about": "a", "copy": "alpha/mods/alpha",
           "patch": "$T/alpha.patch", "keys": {"cmd-alt-a": "mod.open:alpha", "cmd-shift-m": "mod.open:alpha"}},
 "tree": {"repo": "acme/mods", "ref": "2222222222", "license": "MIT", "about": "f", "copy": "tree/mods/tree",
          "needs": ["alpha"], "files_slot": true}}}
EOF
echo '{"global": {"cmd-shift-m": "mod.open:someone-else"}}' > "$H/keys.json"
cat > "$H/layouts/main.json" <<'EOF'
{"id": "root", "type": "row", "children": [{"id": "panel", "type": "column", "size": {"px": 368},
  "children": [{"id": "panel-body", "type": "stack", "children": [{"id": "files", "type": "block", "content": {"mod": "files"}}]}]}]}
EOF
sed 's/"px": 368/"px": 300/' "$H/layouts/main.json" > "$H/layouts/mine2.json"; echo '{"layout": "mine2"}' > "$H/shared.json"
E() { PATH="$T/bin:$PATH" ORC_EXTRAS_SPEC=$T/spec.json ORC_EXTRAS_SRC=$SRC python3 "$REPO/herdr-app/extras.py" "$@"; }
check "extras: --only tree brings what it needs, nothing else" "E --only tree >/dev/null && [ -L '$H/mods/alpha' ] && [ -L '$H/mods/tree' ] && [ ! -e '$H/tool-installed' ]"
check "extras: a copied mod links to its patched build in dist" "[ \"\$(readlink '$H/mods/alpha')\" = '$ORC_DIST/abs${H}/mods/alpha' ] && grep -q 'V = 2' '$H/mods/alpha/main.js' && grep -q 'V = 1' '$SRC/acme-mods/alpha/mods/alpha/main.js' && [ -f '$H/mods/alpha/.orc-extra' ]"
check "extras: free keys added, a taken one left alone" "python3 -c \"import json;g=json.load(open('$H/keys.json'))['global'];assert g['cmd-alt-a']=='mod.open:alpha' and g['cmd-shift-m']=='mod.open:someone-else',g\""
check "extras: files_slot mod takes the Files slot at Herdr's panel width" "python3 -c \"import json;s=json.dumps(json.load(open('$H/layouts/mine2.json')));assert '{\\\"mod\\\": \\\"tree\\\"}' in s and '368' in s,s\""
check "extras: a mod with its own installer runs it from the pinned source" "E >/dev/null && grep -q -- '--app' '$H/tool-installed'"
check "extras: status lists them with their pins" "python3 '$REPO/install.py' --status | grep -q 'extras .*alpha@2222222'"
E --uninstall --only alpha >/dev/null; mkdir -p "$H/mods/alpha" && echo mine > "$H/mods/alpha/main.js"
check "extras: someone else's mod folder is refused" "! E --only alpha >/dev/null && [ \"\$(cat '$H/mods/alpha/main.js')\" = mine ]"
mkdir -p "$T/badbin"; printf '#!/bin/sh\n[ "$1" = check ] && { echo bad mod; exit 1; }\nexit 1\n' > "$T/badbin/herdr-app"; chmod +x "$T/badbin/herdr-app"
check "extras: a build that fails its check leaves the user's mod in place" "! PATH='$T/badbin':\$PATH ORC_EXTRAS_SPEC=$T/spec.json ORC_EXTRAS_SRC=$SRC python3 '$REPO/herdr-app/extras.py' --only alpha --force >/dev/null && [ \"\$(cat '$H/mods/alpha/main.js')\" = mine ] && [ ! -e '$H/alpha.before-orc' ]"
check "extras: --force moves it aside and links ours" "E --only alpha --force >/dev/null && [ -L '$H/mods/alpha' ] && [ -f '$H/alpha.before-orc/main.js' ]"
check "extras: uninstall gives back slot, width and keys, runs the uninstaller, restores the moved mod" "E --uninstall >/dev/null && python3 -c \"import json;s=json.dumps(json.load(open('$H/layouts/mine2.json')));assert '{\\\"mod\\\": \\\"files\\\"}' in s and '300' in s,s;g=json.load(open('$H/keys.json'))['global'];assert 'cmd-alt-a' not in g and g['cmd-shift-m']=='mod.open:someone-else',g\" && [ ! -e '$H/tool-installed' ] && [ ! -L '$H/mods/tree' ] && [ \"\$(cat '$H/mods/alpha/main.js')\" = mine ] && [ ! -e '$ORC_DIST/abs${H}/mods/tree' ]"

mkdir -p "$H/alpha.before-orc" && echo older > "$H/alpha.before-orc/main.js"
check "extras: an earlier .before-orc is never deleted" "! E --only alpha --force >/dev/null && [ \"\$(cat '$H/alpha.before-orc/main.js')\" = older ] && [ \"\$(cat '$H/mods/alpha/main.js')\" = mine ]"
rm -rf "$H/alpha.before-orc" "$H/mods/alpha"
echo '{"global": {"cmd-alt-a": "mod.open:alpha"}}' > "$H/keys.json"
check "extras: a key the user had bound to the same action stays on uninstall" "E --only alpha >/dev/null && E --uninstall --only alpha >/dev/null && python3 -c \"import json;g=json.load(open('$H/keys.json'))['global'];assert g.get('cmd-alt-a')=='mod.open:alpha',g\""

mkdir -p "$T/proj6"; python3 "$REPO/install.py" --cli agy --scope project --project "$T/proj6" >/dev/null
PYDIR=$(dirname "$(command -v python3)")
check "uninstall without --cli removes what is recorded, CLI on PATH or not" "PATH='$T/nobin':/usr/bin:/bin '$PYDIR/python3' '$REPO/install.py' --uninstall --scope project --project '$T/proj6' >/dev/null && [ ! -e '$T/proj6/.agents/agents/hcorc/agent.md' ]"

mkdir -p "$H/mods/alpha" && echo mine > "$H/mods/alpha/main.js"
check "extras: a publish that fails after the check puts the user's mod back" "PATH='$T/bin':\$PATH ORC_EXTRAS_SPEC=$T/spec.json ORC_EXTRAS_SRC=$SRC python3 -c \"
import sys; sys.path.insert(0, '$REPO/herdr-app'); import extras as X
def boom(*a): raise OSError('boom')
X.I.link = boom
sys.exit(0 if X.install(['alpha'], False, True) is False else 1)\" >/dev/null && [ \"\$(cat '$H/mods/alpha/main.js')\" = mine ] && [ ! -e '$H/alpha.before-orc' ]"
rm -rf "$H/mods/alpha"
E --only tool >/dev/null & E --only alpha >/dev/null & wait
check "extras: two runs at once both stay recorded" "python3 -c \"import json,os;m=json.load(open(os.path.expanduser('~/.local/state/orc/installs.json')));e=[v for k,v in m.items() if k.startswith('herdr-app-extras')][0];assert {'tool','alpha'} <= set(e['extras']),e\""
check "extras: a failed upgrade keeps the previously installed build available" "PATH='$T/bin':\$PATH ORC_EXTRAS_SPEC=$T/spec.json ORC_EXTRAS_SRC=$SRC python3 -c \"
import sys; sys.path.insert(0, '$REPO/herdr-app'); import extras as X
from pathlib import Path
from unittest.mock import patch
link = Path('$H/mods/alpha')
before = (link / 'main.js').read_bytes()
rename = Path.rename
def fail_stage(self, target):
    if self.name == 'alpha' and self.parent.name == '.alpha.orc-stage':
        raise OSError('could not move the staged build')
    return rename(self, target)
with patch.object(Path, 'rename', fail_stage):
    assert not X.install(['alpha'], False, False)
assert link.is_symlink() and (link / 'main.js').read_bytes() == before
\" >/dev/null"
E --uninstall >/dev/null

# 13. ./install.sh: every part this machine has, in the same throwaway HOME.
check "install.sh --dry-run walks every step" "PATH='$T/bin':\$PATH XDG_CONFIG_HOME=$X '$REPO/install.sh' --dry-run --cli agy --extras=tree 2>&1 | grep -q 'Herdr app: third-party mods' "
check "install.sh --scope project skips the per-user parts" "'$REPO/install.sh' --cli agy --scope project --project '$P2' 2>&1 | grep -q 'per user, not per project' && [ -L '$P2/.agents/agents/hcorc/agent.md' ]"

# 14. fixes from the code review
# a relative ORC_DIST still gives links that resolve
P3=$T/proj3; mkdir -p "$P3"
check "relative ORC_DIST: links resolve" "(cd '$T' && ORC_DIST=reldist python3 '$REPO/install.py' --cli agy --scope project --project '$P3' >/dev/null) && [ -s '$P3/.agents/agents/hcorc/agent.md' ] && case \"\$(readlink '$P3/.agents/agents/hcorc/agent.md')\" in /*) true;; *) false;; esac"
(cd "$T" && ORC_DIST=reldist python3 "$REPO/install.py" --cli agy --uninstall --scope project --project "$P3" >/dev/null)
# a user's hook sharing an entry (matcher) with ours survives install and uninstall
S2=$T/proj4/.claude/settings.json; mkdir -p "$T/proj4/.claude"
printf '{"hooks": {"PreToolUse": [{"matcher": "Bash", "hooks": [{"type": "command", "command": "mine-too.sh"}, {"type": "command", "command": "/old/clone/shared/bin/guard.py"}]}]}}\n' > "$S2"
I --cli claude --scope project --project "$T/proj4" >/dev/null
check "co-located user hook kept, old guard replaced" "grep -q mine-too.sh '$S2' && [ \$(grep -c 'shared/bin/guard.py' '$S2') = 1 ] && grep -q '$REPO/shared/bin/guard.py' '$S2'"
I --cli claude --uninstall --scope project --project "$T/proj4" >/dev/null
check "uninstall keeps the co-located user hook" "grep -q mine-too.sh '$S2' && ! grep -q guard.py '$S2'"
# a broken settings.json stops only claude, before anything is written, and the rest is recorded
echo '{oops' > "$T/proj4/.claude/settings.json"
OUT=$(I --cli claude,agy --scope project --project "$T/proj4" 2>&1)
check "broken settings.json: claude untouched, agy installed and recorded" "echo \"\$OUT\" | grep -q 'claude\] not installed' && [ ! -e '$T/proj4/.claude/agents/hcorc.md' ] && [ -L '$T/proj4/.agents/agents/hcorc/agent.md' ] && python3 '$REPO/install.py' --status | grep -q 'agy .*proj4'"
I --cli agy --uninstall --scope project --project "$T/proj4" >/dev/null
# the mods: --no-mods keeps them recorded; a renamed marketplace uninstalls the old refs
printf '#!/bin/sh\necho "$*" >> "%s/claude-calls"\nexit 0\n' "$T" > "$T/bin/claude"; chmod +x "$T/bin/claude"
CL() { PATH="$T/bin:$PATH" python3 "$REPO/install.py" --cli claude --scope project --project "$T/proj5" "$@"; }
mkdir -p "$T/proj5"; CL >/dev/null
MARKET=$(python3 -c "import json;print(json.load(open('$REPO/.claude-plugin/marketplace.json'))['name'])")
check "mods installed and recorded" "grep -q 'plugin install orc-cache@$MARKET' '$T/claude-calls' && python3 -c \"import json,os;m=json.load(open(os.path.expanduser('~/.local/state/orc/installs.json')));e=[v for k,v in m.items() if k.endswith('proj5/.claude')][0];assert 'orc-cache@$MARKET' in e['mods'],e\""
CL --no-mods >/dev/null
check "--no-mods keeps them recorded" "python3 -c \"import json,os;m=json.load(open(os.path.expanduser('~/.local/state/orc/installs.json')));e=[v for k,v in m.items() if k.endswith('proj5/.claude')][0];assert e['mods'],e\""
python3 - "$HOME/.local/state/orc/installs.json" <<'PY'
import json,sys
p=sys.argv[1]; m=json.load(open(p))
for k,v in m.items():
    if k.endswith("proj5/.claude"): v["mods"]=["orc-cache@orchestator"]
json.dump(m,open(p,"w"))
PY
: > "$T/claude-calls"; CL >/dev/null
check "old marketplace's refs uninstalled on rerun" "grep -q 'plugin uninstall orc-cache@orchestator' '$T/claude-calls' && grep -q 'plugin marketplace remove orchestator' '$T/claude-calls' && grep -q 'plugin update orc-cache@$MARKET' '$T/claude-calls'"
CL --uninstall >/dev/null
check "uninstall removes the marketplace it recorded" "grep -q 'plugin marketplace remove $MARKET' '$T/claude-calls'"
# herdr-app: a layout the installer did not clone is never deleted
echo '{"layout:main": {"json": "x"}}' > "$H/installed.json"; echo '{"layout": "main"}' > "$H/shared.json"
rm -rf "$H/mods/orc-skills"
HP >/dev/null; rm -f "$H/layouts/main-orc.json"
cp "$H/layouts/main.json" "$H/layouts/mine3.json"
python3 - "$H/layouts/mine3.json" <<'PY'
import json,sys
p=sys.argv[1]
d={"id": "root", "type": "row", "children": [{"id": "work", "type": "column", "children": [
  {"id": "tabs", "type": "block", "size": {"px": 42}, "content": {"mod": "tabs"}},
  {"id": "work-body", "type": "row", "children": [{"id": "main", "type": "block", "content": {"tab": "active"}}]}]}]}
json.dump(d, open(p, "w"))
PY
echo '{"layout": "mine3"}' > "$H/shared.json"
HP >/dev/null
check "herdr-app: reinstall on the user's own layout patches it" "grep -q orc-skills-panel '$H/layouts/mine3.json'"
python3 - "$H/layouts/mine3.json" <<'PY'
import json,sys
p=sys.argv[1]; d=json.load(open(p))
def walk(n):
    if n.get("id")=="orc-skills-bar": n["children"].append({"id":"someone-else","type":"block","content":{"mod":"x"}})
    for c in n.get("children",[]): walk(c)
walk(d); json.dump(d, open(p,"w"))
PY
HP --uninstall >/dev/null
check "herdr-app: uninstall keeps the user's layout and a button someone else added" "[ -f '$H/layouts/mine3.json' ] && grep -q someone-else '$H/layouts/mine3.json' && ! grep -q -E 'orc-skills-(toggle|panel)' '$H/layouts/mine3.json'"

echo "install: pass=$pass fail=$fail"
[ "$fail" = 0 ]
